$slug = { param($x) $s = (($x.ToLower() -replace "[^a-z0-9]+","-").Trim("-")); if ($s.Length -gt 70) { $s = $s.Substring(0,70) }; $s }
"  saving the new Where I'm From and Service & Sacrifice descriptions (" + $d.Count + ")..."
